codeExample.bad:
/* A sticky header sits at a fixed height that fully covers form
   fields as the user tabs down the page, hiding focused elements */
.sticky-header {
  position: fixed;
  top: 0;
  height: 120px;
  z-index: 100;
}
/* No scroll-margin accounts for the header's height, so focused
   elements can end up scrolled completely underneath it */

codeExample.good:
/* Focusable elements get scroll-margin-top matching the sticky
   header's height, so focusing them scrolls them fully into view
   below the header instead of underneath it */
.sticky-header {
  position: fixed;
  top: 0;
  height: 120px;
  z-index: 100;
}
input, button, a, select, textarea {
  scroll-margin-top: 130px;
}
